{
  "work_definition_version": 0,
  "task_family": "reconciliation",
  "model_id": "W1-L-R11-deflabpeers",
  "provenance": {
    "producer": "goose-session-r11",
    "skill": "define-lab-process",
    "produced_at": "2026-09-06"
  },
  "purpose": "Reconcile supplier statement against internal ledger as peer sources, identifying missing records and amount differences within GBP 0.01 tolerance",
  "sources": {
    "supplier-statement": {
      "role_label": "supplier statement",
      "fixture": "supplier-statement.txt",
      "observed_fields": ["Date", "Supplier Name", "InvoiceNumber", "Amount", "Currency", "Status"],
      "basis": "observed"
    },
    "ledger-book": {
      "role_label": "internal ledger book",
      "fixture": "ledger-book.txt",
      "observed_fields": ["Date", "ReferenceNumber", "SupplierName", "InvoiceNumber", "Amount", "Status", "Notes"],
      "basis": "observed"
    }
  },
  "body": {
    "left": "supplier-statement",
    "right": "ledger-book",
    "match_on": {
      "left_field": "InvoiceNumber",
      "right_field": "InvoiceNumber",
      "basis": "human_confirmed",
      "confirmation": "Q_match_key"
    },
    "compare": [
      {
        "field": "Amount",
        "comparison": "within",
        "tolerance": "0.01",
        "basis": "human_confirmed",
        "confirmation": "Q_compare_amount"
      }
    ],
    "classify": {
      "both_same": "match",
      "both_different": "discrepancy",
      "only_left": "missing_from_ledger",
      "only_right": "missing_from_statement"
    },
    "output_order": "left_then_right",
    "on_duplicate_key": "refuse_run",
    "on_non_numeric": "refuse_key"
  },
  "output": {
    "reports_fields": ["InvoiceNumber", "Amount"],
    "context_fields": ["Date", "Supplier Name", "Status"]
  },
  "human_confirmations": [
    {
      "id": "Q_match_key",
      "question": "Which field identifies the same record / invoice in both files?",
      "answer": "InvoiceNumber",
      "basis": "human_confirmed"
    },
    {
      "id": "Q_compare_amount",
      "question": "Should Amount be compared, and if so, how and with what tolerance? Is Currency part of the reconciliation rule? Which file is the source of truth for matching?",
      "answer": "Yes, compare Amount numerically, within 0.01. No. All sample amounts are GBP; Currency is not compared and is not part of the rule. Neither — both are peer sources.",
      "basis": "human_confirmed"
    },
    {
      "id": "Q_report_fields",
      "question": "Which fields should appear in the report row? Which fields are context for the report?",
      "answer": "The match key (InvoiceNumber) and the compared field (Amount). Date, Supplier Name, and Status.",
      "basis": "human_confirmed"
    }
  ],
  "open_questions": [
    {
      "id": "Q_duplicate_handling",
      "question": "Policy for duplicate keys (same InvoiceNumber in both sources with discrepant compared field)",
      "load_bearing": false,
      "status": "unresolved"
    },
    {
      "id": "Q_non_numeric_policy",
      "question": "Handling of non-numeric amounts if such records appear",
      "load_bearing": false,
      "status": "unresolved"
    }
  ],
  "requested_destination": "review_only",
  "requested_delivery": {
    "format": "json_discrepancy_report"
  },
  "requested_authority": null
}

